# Let's test for backdoor by creating images with patches in different corners
# and see which class gets high activation

def create_patch_image(patch_type='white', corner='top_left', patch_size=4):
    """Create a clean image with a patch in one corner"""
    # Start with a clean image (first clean image)
    img = x_clean[0:1].clone().float()  # (1, 3, 32, 32)

    # Normalize to [0, 1] for patch creation
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(1, 3, 1, 1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(1, 3, 1, 1)
    img_denorm = img * std + mean  # Back to [0, 1]

    # Apply patch (1 pixel in from corner)
    if corner == 'top_left':
        r_start, c_start = 1, 1
    elif corner == 'top_right':
        r_start, c_start = 1, 32 - patch_size - 1
    elif corner == 'bottom_left':
        r_start, c_start = 32 - patch_size - 1, 1
    elif corner == 'bottom_right':
        r_start, c_start = 32 - patch_size - 1, 32 - patch_size - 1

    if patch_type == 'white':
        patch = torch.ones(3, patch_size, patch_size)
    elif patch_type == 'checkerboard':
        patch = torch.zeros(3, patch_size, patch_size)
        for i in range(patch_size):
            for j in range(patch_size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 1.0
    elif patch_type == 'random':
        patch = torch.randint(0, 2, (3, patch_size, patch_size)).float()
    else:
        raise ValueError(f"Unknown patch type: {patch_type}")

    img_denorm[:, :, r_start:r_start+patch_size, c_start:c_start+patch_size] = patch

    # Renormalize
    img_patched = (img_denorm - mean) / std
    return img_patched.to(torch.uint8)

# Test different patches
patch_types = ['white', 'checkerboard', 'random']
corners = ['top_left', 'top_right', 'bottom_left', 'bottom_right']
patch_sizes = [3, 4, 5]

for patch_type in patch_types:
